import re
p='shop/checkout.py'
s=open(p,encoding='utf-8').read()
start=s.index('def process_order(')
end=s.index('def refund_order(')
new='''def process_order(
    order: Order,
    customer: Customer,
    inventory: Inventory,
    gateway: PaymentGateway,
    notifier: ReceiptNotifier,
    coupons: CouponBook,
) -> str:
    """Checks out the order and returns the receipt id of the payment."""
    _validate_items(order)
    total = _calculate_total(order, customer, coupons)
    _reserve_items(order, inventory)
    receipt_id = _charge_or_release(order, customer, total, inventory, gateway)
    _finalize_paid_order(order, total, inventory, coupons)
    _send_receipt(order, customer, receipt_id, notifier)
    return receipt_id


def _validate_items(order: Order) -> None:
    if not order.items:
        raise OrderRejected("order has no items")
    for item in order.items:
        if item.quantity <= 0:
            raise OrderRejected(f"invalid quantity for {item.sku}")


def _calculate_total(order: Order, customer: Customer, coupons: CouponBook) -> int:
    subtotal = sum(item.unit_price_cents * item.quantity for item in order.items)
    tax = _calculate_tax(order, customer)
    discount = _calculate_discount(order, customer, subtotal, coupons)
    shipping = 0 if subtotal - discount >= FREE_SHIPPING_FROM_CENTS else SHIPPING_CENTS
    return subtotal - discount + tax + shipping


def _calculate_tax(order: Order, customer: Customer) -> int:
    """Tax is rounded per line, as the accounting export expects, and is charged on the undiscounted line price."""
    rate = tax_rate(customer.country)
    tax = 0
    for item in order.items:
        line_cents = item.unit_price_cents * item.quantity
        tax += int((Decimal(line_cents) * rate).quantize(Decimal("1"), rounding=ROUND_HALF_UP))
    return tax


def _calculate_discount(order: Order, customer: Customer, subtotal: int, coupons: CouponBook) -> int:
    discount = 0
    if order.coupon is not None:
        discount += _coupon_discount(order.coupon, subtotal, coupons)
    if customer.vip:
        discount += (subtotal - discount) * VIP_DISCOUNT_PERCENT // 100
    return discount


def _coupon_discount(coupon: str, subtotal: int, coupons: CouponBook) -> int:
    percent = coupons.discount_percent(coupon)
    if percent is None:
        raise OrderRejected(f"invalid coupon: {coupon}")
    return subtotal * percent // 100


def _reserve_items(order: Order, inventory: Inventory) -> None:
    reserved = []
    try:
        for item in order.items:
            inventory.reserve(item.sku, item.quantity)
            reserved.append(item)
    except OutOfStock as error:
        _release_items(reserved, inventory)
        order.status = "rejected"
        raise OrderRejected(f"out of stock: {error.sku}") from error


def _release_items(items: list, inventory: Inventory) -> None:
    for item in items:
        inventory.release(item.sku, item.quantity)


def _charge_or_release(
    order: Order, customer: Customer, total: int, inventory: Inventory, gateway: PaymentGateway
) -> str:
    try:
        return gateway.charge(customer.email, total)
    except PaymentDeclined as error:
        _release_items(order.items, inventory)
        order.status = "payment_failed"
        raise OrderRejected(f"payment declined: {error}") from error


def _finalize_paid_order(order: Order, total: int, inventory: Inventory, coupons: CouponBook) -> None:
    for item in order.items:
        inventory.commit(item.sku, item.quantity)
    if order.coupon is not None:
        coupons.redeem(order.coupon)
    order.status = "paid"
    order.total_cents = total
    logger.info("order %s paid: %s cents", order.id, total)


def _send_receipt(order: Order, customer: Customer, receipt_id: str, notifier: ReceiptNotifier) -> None:
    try:
        notifier.send_receipt(customer.email, order.id, receipt_id)
    except Exception:
        logger.warning("receipt for order %s could not be sent", order.id, exc_info=True)


'''
open(p,'w',encoding='utf-8',newline='').write(s[:start]+new+s[end:])
EOF
